    /// <summary>
    ///   Returns GeoJSON region IDs whose bounding box contains the given point.
    ///   Results are conservative (bbox may include points outside the actual polygon).
    /// </summary>
    public static IEnumerable<string> GetRegionsForPoint(double lat, double lon)
    {
        foreach ((string id, (double w, double s, double e, double n)) in All)
        {
            if (lon >= w && lon <= e && lat >= s && lat <= n)
                yield return id;
        }
    }
